function f(x: boolean): number[] | string {
  if (x) { return [1, 2]; }
  return "no";
}
function main(): void {
  const a = f(true);
  console.log(a, f(false));
  if (typeof a === "string") console.log("str", a); else console.log("arr", a.length, a.indexOf(2), a.map(x => x + 1));
  if (Array.isArray(a)) console.log("is arr", a.length);
}
